WITH UserFirstBadges AS (
    SELECT
        UserId,
        MIN(Date) AS FirstBadgeDate,
        MIN(Name) FILTER (WHERE Class = 1) AS FirstGoldBadge,
        MIN(Name) FILTER (WHERE Class = 2) AS FirstSilverBadge,
        MIN(Name) FILTER (WHERE Class = 3) AS FirstBronzeBadge
    FROM Badges
    GROUP BY UserId
),
